(function(){'use strict';
var store=null,ctx=null,dialog=null,content=null,heading=null,trip=null,people=[],delivery=null,documents=[],reservations=[],mode='';
var categories=[['air_tickets','Pasajes aéreos'],['lodging','Alojamiento / hotel'],['transfers','Traslados'],['excursions','Excursiones'],['travel_assistance','Asistencia al viajero'],['cruises','Cruceros'],['other','Otros documentos']];
function el(tag,text,cls){var n=document.createElement(tag);if(text!==undefined&&text!==null)n.textContent=text;if(cls)n.className=cls;return n}
function button(text,action,cls,data){var b=el('button',text,cls||'btn btn--secondary btn--small');b.type='button';b.dataset.action=action;Object.keys(data||{}).forEach(k=>b.dataset[k]=data[k]);return b}
function submitButton(text,cls){var b=el('button',text,cls||'btn btn--primary btn--small');b.type='submit';return b}
function label(text,control){var l=el('label',null,'stage3b-field');l.append(el('span',text),control);return l}
function input(type,value,attrs){var n=el('input');n.type=type;n.value=value||'';Object.keys(attrs||{}).forEach(k=>n.setAttribute(k,attrs[k]));return n}
function select(options,value){var s=el('select');options.forEach(o=>{var x=el('option',o[1]);x.value=o[0];x.selected=String(o[0])===String(value||'');s.append(x)});return s}
function close(){if(dialog.open)dialog.close();mode='';trip=null;delivery=null}
function fmtDate(value){if(!value)return 'Sin fecha';var d=new Date(value.length===10?value+'T12:00:00':value);return isNaN(d)?value:new Intl.DateTimeFormat('es-AR',{dateStyle:'medium'}).format(d)}
function fmtTime(value){if(!value)return 'Sin horario';var d=new Date(value);return isNaN(d)?value:new Intl.DateTimeFormat('es-AR',{dateStyle:'short',timeStyle:'short'}).format(d)}
function fmtSize(bytes){var n=Number(bytes)||0;return n>=1048576?(n/1048576).toFixed(1)+' MiB':Math.ceil(n/1024)+' KiB'}
function appMessage(text,kind){if(ctx&&ctx.setStatus)ctx.setStatus(text,kind||'')}
function reportDialogError(error){var message=error&&error.message||'No se pudo completar la operación. Revisá la conexión y el estado remoto.';appMessage(message,'error');if(content){var note=content.querySelector('.stage3b-inline-error');if(!note){note=el('p',null,'form-error stage3b-inline-error');note.setAttribute('role','alert');content.prepend(note)}note.textContent=message}}
function linkFor(token){var url=new URL('documentacion-pasajero.html',location.href);url.hash=token;return url.href}
function tripPeople(id){var ids=new Set(ctx.links.filter(x=>String(x.trip_id)===String(id)).map(x=>String(x.passenger_id)));return ctx.passengers.filter(x=>ids.has(String(x.id)))}
function personName(p){return [p.first_name,p.last_name].filter(Boolean).join(' ')}
function renderTripList(){var list=document.querySelector('#delivery-trip-list');if(!list)return;list.replaceChildren();var map=new Map((ctx.deliveries||[]).map(d=>[String(d.trip_id),d]));
 ctx.trips.forEach(t=>{var card=el('article',null,'stage3b-trip-card');var info=el('div');info.append(el('h3',t.trip_name||t.destination),el('p',t.destination+' · '+fmtDate(t.departure_on)+' — '+fmtDate(t.return_on)));var d=map.get(String(t.id));info.append(el('small',d?('Enlace: '+({active:'Activo',revoked:'Revocado',draft:'Borrador'}[d.status]||d.status)):'Todavía sin enlace','stage3b-state'));var actions=el('div',null,'stage3b-actions');actions.append(button('Documentación','manage-docs','btn btn--primary btn--small',{tripId:t.id}),button('Reservas aéreas','manage-air','btn btn--secondary btn--small',{tripId:t.id}));card.append(info,actions);list.append(card)});
 if(!ctx.trips.length)list.append(el('article','Primero registrá un viaje para gestionar sus documentos y reservas.','surface section-empty'));
 var metric=document.querySelector('#metric-deliveries');if(metric)metric.textContent=String((ctx.deliveries||[]).filter(d=>d.status==='active').length);
}
async function reloadDeliveries(){ctx.deliveries=await store.listDeliveries();renderTripList()}
function baseDialog(title){dialog=document.querySelector('#stage3b-manager-dialog');content=document.querySelector('#stage3b-manager-content');heading=document.querySelector('#stage3b-manager-title');heading.textContent=title;content.replaceChildren();dialog.showModal()}
async function openDocs(tripId){trip=ctx.trips.find(x=>String(x.id)===String(tripId));if(!trip)return;people=tripPeople(trip.id);mode='docs';baseDialog('Documentación · '+(trip.trip_name||trip.destination));content.append(el('p','Cargando entrega segura…','muted-note'));
 try{if(!people.length)throw new Error('Este viaje no tiene pasajeros asociados. Asociá al menos una persona antes de preparar la entrega.');var primary=ctx.links.find(x=>String(x.trip_id)===String(trip.id)&&x.relationship==='primary')||ctx.links.find(x=>String(x.trip_id)===String(trip.id));var result=await store.admin('ensure',{tripId:trip.id,primaryPassengerId:primary&&primary.passenger_id});delivery=result.delivery;delivery.token=result.token;documents=await store.listDocuments(delivery.id);renderDocs()}
 catch(error){content.replaceChildren(el('p',error.message||'No se pudo preparar la entrega.','form-error'))}}
function renderDocs(){content.replaceChildren();var status=el('div',null,'stage3b-status');status.append(el('strong','Enlace: '+({draft:'Borrador',active:'Activo',revoked:'Revocado'}[delivery.status]||delivery.status)),el('span','Compartido por todos los pasajeros; quien reciba el enlace podrá consultar la documentación habilitada.'));
 var linkInput=input('text',linkFor(delivery.token),{readonly:'readonly','aria-label':'Enlace de documentación'});linkInput.className='stage3b-link-value';var linkbar=el('div',null,'stage3b-linkbar');var copyLink=button('Copiar enlace','copy-link','btn btn--secondary btn--small');copyLink.disabled=delivery.status!=='active';linkbar.append(linkInput,copyLink);
 var linkActions=el('div',null,'stage3b-actions');if(delivery.status==='active'){linkActions.append(button('Revocar enlace','revoke-link','btn btn--danger btn--small'),button('Compartir por WhatsApp','share-whatsapp','btn btn--whatsapp btn--small'))}else linkActions.append(button(delivery.status==='revoked'?'Reactivar enlace':'Activar enlace','activate-link','btn btn--primary btn--small'));
 var principal=select(people.map(p=>[p.id,personName(p)]),delivery.primary_passenger_id);var primaryWrap=label('Pasajero principal',principal);var savePrincipal=button('Guardar principal','save-primary','btn btn--secondary btn--small');
 var share=el('section',null,'stage3b-share');share.append(el('h3','Mensaje para WhatsApp'));var phone=input('tel',(people.find(p=>String(p.id)===String(delivery.primary_passenger_id))||{}).whatsapp||(people.find(p=>String(p.id)===String(delivery.primary_passenger_id))||{}).phone||'',{placeholder:'Teléfono internacional, por ejemplo +549...'});phone.dataset.sharePhone='';var message=el('textarea');message.rows=4;message.dataset.shareMessage='';message.value=delivery.whatsapp_message||shareMessage();share.append(primaryWrap,savePrincipal,label('Número de WhatsApp',phone),label('Mensaje editable',message));var wa=el('a','Abrir WhatsApp','btn btn--whatsapp');wa.target='_blank';wa.rel='noopener noreferrer';wa.dataset.shareAnchor='';if(delivery.status==='active')wa.href=whatsAppUrl(phone.value,message.value);share.append(wa,el('small','El mensaje queda preparado; el envío lo realiza Javier manualmente.'));
 var docsHeading=el('div',null,'stage3b-section-head');docsHeading.append(el('h3','Documentos PDF'));docsHeading.append(el('p','Los documentos asociados a una persona quedan solo en el panel administrativo; el enlace compartido muestra únicamente documentos del viaje completo.'));
 var form=el('form',null,'stage3b-upload-form');form.dataset.form='document';var file=input('file','',{accept:'application/pdf,.pdf',required:'required'});file.dataset.file='';var title=input('text','',{required:'required',maxlength:'180',placeholder:'Ej.: Voucher de hotel'});title.dataset.docTitle='';var category=select(categories,'other');category.dataset.docCategory='';var passengerOpts=[['','Viaje completo (visible en el portal)']].concat(people.map(p=>[p.id,'Solo panel · '+personName(p)]));var passenger=select(passengerOpts,'');passenger.dataset.docPassenger='';form.append(label('Archivo PDF · máximo 50 MiB',file),label('Título descriptivo',title),label('Tipo de documento',category),label('Asociación',passenger),submitButton('Subir PDF'));
 var rows=el('div',null,'stage3b-document-list');if(!documents.length)rows.append(el('p','Todavía no hay documentos cargados.','muted-note'));
 documents.forEach(d=>{var row=el('article',null,'stage3b-document');var meta=el('div');meta.append(el('strong',d.description||d.file_name),el('small',(categories.find(x=>x[0]===d.category)||['','Otro'])[1]+' · '+fmtSize(d.size_bytes)+' · '+fmtDate(d.created_at)+' · '+(d.passenger_id?(personName(people.find(p=>String(p.id)===String(d.passenger_id))||{})||'Pasajero'):'Viaje completo')));var editTitle=input('text',d.description||'');editTitle.dataset.rowTitle=d.id;var editCategory=select(categories,d.category);editCategory.dataset.rowCategory=d.id;var editPassenger=select(passengerOpts,d.passenger_id||'');editPassenger.dataset.rowPassenger=d.id;var controls=el('div',null,'stage3b-actions');controls.append(button('Guardar datos','save-doc','btn btn--secondary btn--small',{id:d.id}),button('Reemplazar PDF','replace-doc','btn btn--secondary btn--small',{id:d.id}),button('Descargar','download-doc','btn btn--secondary btn--small',{id:d.id}),button('Eliminar','delete-doc','btn btn--danger btn--small',{id:d.id}));var replace=input('file','',{accept:'application/pdf,.pdf'});replace.hidden=true;replace.dataset.replaceFile=d.id;row.append(meta,label('Título',editTitle),label('Tipo',editCategory),label('Asociación',editPassenger),replace,controls);rows.append(row)});
 content.append(status,linkbar,linkActions,share,docsHeading,form,rows);
}
function shareMessage(){var p=people.find(x=>String(x.id)===String(delivery.primary_passenger_id))||people[0];var name=p?personName(p):'grupo';return '¡Hola, '+name+'! 😊✈️\n\nPreparé la documentación de tu viaje a '+trip.destination+'. Podés consultarla acá:\n'+linkFor(delivery.token)+'\n\nJavier\nTu asesor de viajes en Tresor Travel ✈️'}
function whatsAppUrl(phone,message){if(!window.PassengerAgendaStore)return '#';var n=window.PassengerAgendaStore.normalizeWhatsAppNumber(phone);return n?'https://wa.me/'+n+'?text='+encodeURIComponent(message):'#'}
function formatLocal(value){if(!value)return '';var d=new Date(value);if(isNaN(d))return '';d=new Date(d.getTime()-d.getTimezoneOffset()*60000);return d.toISOString().slice(0,16)}
function flightRow(value,index){var row=el('fieldset',null,'stage3b-flight-row');row.dataset.flightIndex=String(index);row.dataset.flightId=value&&value.id||'';row.append(el('legend','Tramo '+(index+1)));var fields=[['flight_number','N.º de vuelo','text'],['origin','Origen','text'],['destination','Destino','text'],['departure_at','Salida','datetime-local'],['arrival_at','Llegada','datetime-local']];fields.forEach(([key,name,type])=>{var v=value&&value[key]||'';if(type==='datetime-local')v=formatLocal(v);var n=input(type,v,{required:key!=='flight_number'});n.dataset.flightField=key;row.append(label(name,n))});row.append(button('Quitar tramo','remove-flight','btn btn--danger btn--small'));return row}
async function openAir(tripId,reservationId){trip=ctx.trips.find(x=>String(x.id)===String(tripId));if(!trip)return;mode='air';baseDialog('Reservas aéreas · '+(trip.trip_name||trip.destination));content.append(el('p','Cargando reservas…','muted-note'));try{reservations=await store.listReservations(trip.id);renderAir(reservationId)}catch(error){content.replaceChildren(el('p',error.message||'No se pudieron cargar las reservas.','form-error'))}}
function renderAir(editId){content.replaceChildren();var title=el('p','Registrá una o más reservas, PNR, pasajeros, vuelos y datos de check-in.','muted-note');content.append(title,button('＋ Agregar reserva','new-reservation','btn btn--primary btn--small',{tripId:trip.id}));
 if(!reservations.length)content.append(el('p','No hay reservas aéreas para este viaje.','muted-note'));
 reservations.forEach(r=>{var card=el('article',null,'stage3b-reservation');card.append(el('h3',(r.airline_name||'Aerolínea')+' · PNR '+r.pnr),el('p','Check-in: '+fmtTime(r.checkin_opens_at)));var pnames=r.passengerIds.map(id=>personName(people.find(p=>String(p.id)===String(id))||{})).filter(Boolean);card.append(el('p','Pasajeros: '+(pnames.join(', ')||'Sin asociación específica')));if(r.official_checkin_url&&/^https:\/\//i.test(r.official_checkin_url)){var a=el('a','Web check-in');a.href=r.official_checkin_url;a.target='_blank';a.rel='noopener noreferrer';card.append(a)}r.flights.forEach(f=>card.append(el('p',(f.flight_number?f.flight_number+' · ':'')+f.origin+' → '+f.destination+' · '+fmtTime(f.departure_at)+' — '+fmtTime(f.arrival_at))));var controls=el('div',null,'stage3b-actions');controls.append(button('Editar','edit-reservation','btn btn--secondary btn--small',{id:r.id,tripId:trip.id}),button('Eliminar','delete-reservation','btn btn--danger btn--small',{id:r.id,tripId:trip.id}));card.append(controls);content.append(card)});
 if(editId)showReservationForm(reservations.find(r=>String(r.id)===String(editId))||null);
}
function showReservationForm(record){var old=document.querySelector('#reservation-form');if(old)old.remove();var form=el('form',null,'stage3b-reservation-form');form.dataset.form='reservation';form.dataset.id=record?.id||'';var airline=input('text',record?.airline_name||'',{required:'required'});airline.name='airline_name';var pnr=input('text',record?.pnr||'',{required:'required'});pnr.name='pnr';var checkin=input('datetime-local',formatLocal(record?.checkin_opens_at),{});checkin.name='checkin_opens_at';var checkinUrl=input('url',record?.official_checkin_url||'',{placeholder:'https://sitio-oficial-de-aerolinea'});checkinUrl.name='official_checkin_url';var notes=el('textarea');notes.name='notes';notes.value=record?.notes||'';form.append(el('h3',record?'Editar reserva':'Nueva reserva'),label('Aerolínea',airline),label('Código PNR',pnr),label('Apertura de check-in (si está confirmada)',checkin),label('Enlace oficial de check-in',checkinUrl),label('Observaciones',notes));var passengersBox=el('fieldset',null,'stage3b-passenger-options');passengersBox.append(el('legend','Pasajeros de esta reserva'));people.forEach(p=>{var l=el('label',null,'stage3b-checkbox');var cb=input('checkbox','');cb.value=p.id;cb.dataset.resPassenger='';cb.checked=!!record?.passengerIds.some(id=>String(id)===String(p.id));l.append(cb,el('span',personName(p)));passengersBox.append(l)});form.append(passengersBox);var flightWrap=el('div',null,'stage3b-flights');flightWrap.dataset.flights='';(record?.flights?.length?record.flights:[{}]).forEach((f,i)=>flightWrap.append(flightRow(f,i)));form.append(flightWrap,button('＋ Agregar tramo','add-flight','btn btn--secondary btn--small'),submitButton('Guardar reserva'));content.prepend(form)}
function openShareUrl(){return document.querySelector('.stage3b-link-value')?.value||''}
async function action(event){var b=event.target.closest('[data-action]');if(!b)return;var act=b.dataset.action;try{
 if(act==='manage-docs'){await openDocs(b.dataset.tripId);return} if(act==='manage-air'){await openAir(b.dataset.tripId);return}if(act==='close-stage3b'){close();return}
 if(act==='copy-link'){await navigator.clipboard.writeText(openShareUrl());appMessage('Enlace copiado. Compartilo solo con los pasajeros del viaje.','success');return}
 if(act==='activate-link'||act==='revoke-link'){if(act==='revoke-link'&&!confirm('¿Revocar el enlace? Los pasajeros dejarán de acceder hasta que lo reactives.'))return;var status=act==='revoke-link'?'revoked':'active';var out=await store.admin('set-status',{deliveryId:delivery.id,status});delivery=out.delivery;delivery.token=out.token;documents=await store.listDocuments(delivery.id);renderDocs();appMessage(status==='active'?'Enlace activado.':'Enlace revocado.','success');return}
 if(act==='save-primary'){var selectEl=content.querySelector('.stage3b-field select');var out=await store.admin('ensure',{tripId:trip.id,primaryPassengerId:selectEl.value});delivery=out.delivery;delivery.token=out.token;documents=await store.listDocuments(delivery.id);renderDocs();appMessage('Pasajero principal actualizado.','success');return}
 if(act==='share-whatsapp'){var a=content.querySelector('[data-share-anchor]');var phone=content.querySelector('[data-share-phone]').value;var message=content.querySelector('[data-share-message]').value;var href=whatsAppUrl(phone,message);if(href==='#'){appMessage('Ingresá un número de WhatsApp válido con código de país.','error');return}var shareTab=window.open('about:blank','_blank');if(!shareTab){appMessage('Permití una ventana emergente para abrir WhatsApp.','error');return}shareTab.opener=null;shareTab.location=href;return}
 if(act==='download-doc'){var doc=documents.find(x=>String(x.id)===String(b.dataset.id));if(!doc)return;var tab=window.open('about:blank','_blank');if(!tab){appMessage('Permití la ventana emergente para descargar el documento.','error');return}tab.opener=null;tab.location=await store.downloadDocument(doc);return}
 if(act==='delete-doc'){var doc=documents.find(x=>String(x.id)===String(b.dataset.id));if(!doc||!confirm('¿Eliminar este PDF del bucket privado?'))return;await store.deleteDocument(doc);documents=await store.listDocuments(delivery.id);renderDocs();appMessage('Documento eliminado.','success');return}
 if(act==='replace-doc'){if(!confirm('¿Reemplazar este PDF? Se conservará la ficha del documento.'))return;var inp=content.querySelector('[data-replace-file="'+CSS.escape(b.dataset.id)+'"]');inp.click();return}
 if(act==='save-doc'){var id=b.dataset.id;await store.updateDocument(id,{description:content.querySelector('[data-row-title="'+CSS.escape(id)+'"]').value,category:content.querySelector('[data-row-category="'+CSS.escape(id)+'"]').value,passenger_id:content.querySelector('[data-row-passenger="'+CSS.escape(id)+'"]').value});documents=await store.listDocuments(delivery.id);renderDocs();appMessage('Ficha del documento actualizada.','success');return}
 if(act==='new-reservation'){showReservationForm(null);return}if(act==='edit-reservation'){await openAir(b.dataset.tripId,b.dataset.id);return}
 if(act==='delete-reservation'){if(!confirm('¿Eliminar esta reserva, sus vuelos y asociaciones?'))return;await store.deleteReservation(trip.id,b.dataset.id);reservations=await store.listReservations(trip.id);renderAir();appMessage('Reserva eliminada.','success');return}
 if(act==='add-flight'){content.querySelector('[data-flights]').append(flightRow({},content.querySelectorAll('.stage3b-flight-row').length));return}
 if(act==='remove-flight'){b.closest('.stage3b-flight-row').remove();return}
 }catch(error){reportDialogError(error)}
}
async function submit(event){var form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();var submitButton=form.querySelector('button[type="submit"]');if(submitButton)submitButton.disabled=true;try{
 if(form.dataset.form==='document'){var file=form.querySelector('[data-file]').files[0];await store.addDocument(delivery,file,{description:form.querySelector('[data-doc-title]').value,category:form.querySelector('[data-doc-category]').value,passenger_id:form.querySelector('[data-doc-passenger]').value});documents=await store.listDocuments(delivery.id);renderDocs();appMessage('PDF cargado en el bucket privado.','success')}
 else if(form.dataset.form==='reservation'){var fields=Object.fromEntries(new FormData(form).entries());var flights=Array.from(form.querySelectorAll('.stage3b-flight-row')).map((row,i)=>{var o={id:row.dataset.flightId||null,display_order:i};row.querySelectorAll('[data-flight-field]').forEach(n=>o[n.dataset.flightField]=n.value);o.departure_at=o.departure_at?new Date(o.departure_at).toISOString():null;o.arrival_at=o.arrival_at?new Date(o.arrival_at).toISOString():null;return o});if(flights.some(f=>!f.origin||!f.destination||!f.departure_at||!f.arrival_at))throw new Error('Completá origen, destino y horarios de cada tramo.');if(flights.some(f=>new Date(f.arrival_at)<new Date(f.departure_at)))throw new Error('La llegada no puede ser anterior a la salida.');if(fields.official_checkin_url&&!/^https:\/\//i.test(fields.official_checkin_url))throw new Error('El enlace de check-in debe comenzar con https://.');var ids=Array.from(form.querySelectorAll('[data-res-passenger]:checked')).map(x=>x.value);await store.saveReservation(trip.id,{id:form.dataset.id||null,airline_name:fields.airline_name,pnr:fields.pnr,checkin_opens_at:fields.checkin_opens_at?new Date(fields.checkin_opens_at).toISOString():null,official_checkin_url:fields.official_checkin_url,notes:fields.notes},ids,flights);reservations=await store.listReservations(trip.id);renderAir();appMessage('Reserva y tramos guardados.','success')}
 }catch(error){reportDialogError(error)}finally{if(submitButton)submitButton.disabled=false}}
function onChange(event){var n=event.target;if(n.matches('[data-replace-file]')&&n.files?.[0]){var row=documents.find(x=>String(x.id)===String(n.dataset.replaceFile));store.replaceDocument(row,n.files[0]).then(()=>store.listDocuments(delivery.id)).then(items=>{documents=items;renderDocs();appMessage('PDF reemplazado conservando el identificador del documento.','success')}).catch(e=>reportDialogError(e))}}
function refresh(data){ctx=Object.assign(ctx||{},data);if(store)renderTripList()}
async function init(options){ctx=Object.assign({},options);try{store=window.PassengerDocumentsStore.create(ctx.cloud,ctx.workspace.id);dialog=document.querySelector('#stage3b-manager-dialog');content=document.querySelector('#stage3b-manager-content');heading=document.querySelector('#stage3b-manager-title');document.addEventListener('click',action);dialog.addEventListener('click',event=>{if(event.target===dialog)close()});dialog.addEventListener('click',event=>{if(event.target.matches('[data-action]'))event.preventDefault()});dialog.addEventListener('submit',submit);dialog.addEventListener('change',onChange);await reloadDeliveries()}catch(error){ctx.deliveries=[];renderTripList();appMessage('La agenda sigue disponible, pero la gestión de documentos no pudo inicializarse. Revisá la instalación de Etapa 3A y las políticas RLS.','error')}}
window.PassengerDocsUI={init,refresh};
})();
